method add(lst: seq<int>) returns (result: int)
    requires |lst| > 0 // lst is a non-empty list
    ensures result == SumEvenAtOddIndices(lst)
{
    var sum := 0;
    // Loop through the list to sum up even elements at odd indices
    var i := 1; // Start from the first odd index
    while i < |lst|
        invariant 0 <= i <= |lst| // i is within bounds of the list
        invariant sum == SumEvenAtOddIndices(Slice(lst, 0, i)) // sum of even elements at odd indices so far
    {
        if lst[i] % 2 == 0 {
            sum := sum + lst[i];
        }
        i := i + 2; // Move to the next odd index
    }
    result := sum;
}

